define('taoQtiItem/qtiCreator/editor/styleEditor/styleSheetToggler',['jquery', 'lodash', 'i18n', 'taoQtiItem/qtiCreator/editor/styleEditor/styleEditor', 'taoQtiItem/qtiCreator/model/Stylesheet', 'tpl!taoQtiItem/qtiCreator/tpl/notifications/genericFeedbackPopup', 'ui/dialog/confirm', 'ui/resourcemgr'], function ($, _, __, styleEditor, Stylesheet, genericFeedbackPopup, confirmDialog) {
  'use strict';

  var $doc = $(document);
  var styleSheetToggler = function () {
    var init = function init(itemConfig) {
      var _createInfoBox = function _createInfoBox(data) {
        var $messageBox = $(genericFeedbackPopup(data)),
          closeTrigger = $messageBox.find('.close-trigger');
        $('body').append($messageBox);
        closeTrigger.on('click', function () {
          $messageBox.fadeOut(function () {
            $(this).remove();
          });
        });
        setTimeout(function () {
          closeTrigger.trigger('click');
        }, 4000);
        return $messageBox;
      };
      var cssToggler = $('#style-sheet-toggler'),
        uploader = $('#stylesheet-uploader'),
        customCssToggler = $('[data-custom-css]'),
        getContext = function getContext(trigger) {
          trigger = $(trigger);
          var li = trigger.closest('li');
          var stylesheetObj = li.data('stylesheetObj') || new Stylesheet({
            href: li.data('css-res')
          });
          var input = li.find('.style-sheet-label-editor');
          var labelBox = input.prev('.file-label');
          var label = input.val();
          return {
            li: li,
            input: input,
            label: label,
            labelBox: labelBox,
            isCustomCss: !!li.data('custom-css'),
            isDisabled: li.find('.icon-preview').hasClass('disabled'),
            stylesheetObj: stylesheetObj,
            cssUri: stylesheetObj.attr('href')
          };
        };
      uploader.on('click', function () {
        uploader.resourcemgr({
          className: 'stylesheets',
          appendContainer: '#mediaManager',
          path: '/',
          root: 'local',
          browseUrl: itemConfig.getFilesUrl,
          uploadUrl: itemConfig.fileUploadUrl,
          deleteUrl: itemConfig.fileDeleteUrl,
          downloadUrl: itemConfig.fileDownloadUrl,
          fileExistsUrl: itemConfig.fileExistsUrl,
          params: {
            uri: itemConfig.uri,
            lang: itemConfig.lang,
            filters: 'text/css'
          },
          pathParam: 'path',
          select(e, files) {
            var l = files.length;
            for (var i = 0; i < l; i++) {
              styleEditor.addStylesheet(files[i].file);
            }
          },
          hooks: {
            deleteFile(file) {
              var filePath = [file];
              if (file.startsWith('/')) {
                filePath.push(file.substring(1));
              }
              var $style = cssToggler.find(filePath.map(path => "[data-css-res=\"".concat(path, "\"]")).join(', '));
              if ($style.length) {
                return new Promise((resolve, reject) => {
                  confirmDialog(__('As this stylesheet is attached to the item, the item will be automatically saved after the deletion, continue?'), () => {
                    $('#mediaManager').one('filedelete.resourcemgr', () => {
                      deleteStylesheet($style);
                      $('#item-editor-panel').trigger('beforesave.qti-creator').trigger('save.qti-creator');
                    });
                    resolve();
                  }, reject);
                });
              }
            }
          }
        });
      });
      var deleteStylesheet = function deleteStylesheet(trigger) {
        var context = getContext(trigger),
          attr = context.isDisabled ? 'disabled-href' : 'href',
          cssLinks = $('head link');
        styleEditor.getItem().removeStyleSheet(context.stylesheetObj);
        cssLinks.filter("[".concat(attr, "*=\"").concat(context.cssUri, "\"]")).remove();
        context.li.remove();
        $('.feedback-info').hide();
        _createInfoBox({
          message: __('Style Sheet <b>%s</b> removed<br> Click <i>Add Style Sheet</i> to re-apply.').replace('%s', context.label),
          type: 'info'
        });
        $doc.trigger('customcssloaded.styleeditor', [styleEditor.getStyle()]);
      };
      var initLabelEditor = function initLabelEditor(trigger) {
        var context = getContext(trigger);
        context.labelBox.hide();
        context.input.show();
      };
      var downloadStylesheet = function downloadStylesheet(trigger) {
        styleEditor.download(getContext(trigger).cssUri);
      };
      var saveLabel = function saveLabel(trigger) {
        var context = getContext(trigger),
          title = $.trim(context.input.val());
        if (!title) {
          context.stylesheetObj.attr('title', '');
          return false;
        }
        context.stylesheetObj.attr('title', title);
        context.input.hide();
        context.labelBox.html(title).show();
      };
      var handleAvailability = function handleAvailability(trigger) {
        var context = getContext(trigger);
        if (context.isCustomCss || !context.label) {
          if (context.isDisabled) {
            $('#item-editor-user-styles')[0].disabled = false;
            customCssToggler.removeClass('not-available');
          } else {
            $('#item-editor-user-styles')[0].disabled = true;
            customCssToggler.addClass('not-available');
          }
        } else {
          var linkDom = Object.values(document.styleSheets).find(sheet => typeof sheet.href === 'string' && sheet.href.includes(context.label));
          if (context.isDisabled) {
            linkDom.disabled = false;
          } else {
            linkDom.disabled = true;
          }
        }
        $(trigger).toggleClass('disabled');
      };
      cssToggler.on('click', function (e) {
        var target = e.target,
          className = target.className;
        if (className.indexOf('icon-bin') > -1) {
          deleteStylesheet(e.target);
        } else if (className.indexOf('file-label') > -1) {
          initLabelEditor(e.target);
        } else if (className.indexOf('icon-preview') > -1) {
          handleAvailability(e.target);
        } else if (className.indexOf('icon-download') > -1) {
          downloadStylesheet(e.target);
        }
      });
      cssToggler.on('keydown', 'input', function (e) {
        if (e.keyCode === 13) {
          $(e.target).trigger('blur');
        }
      });
      cssToggler.on('blur', 'input', function (e) {
        saveLabel(e.target);
      });
    };
    return {
      init: init
    };
  }();
  return styleSheetToggler;
});
