define('taoQtiItem/qtiCreator/helper/textEntryEvaluationSave',['taoQtiItem/qtiCreator/helper/textEntryEvaluationForm', 'taoQtiItem/qtiCreator/helper/textEntryEvaluationHelper'], function (textEntryEvaluationForm, evaluationHelper) {
  'use strict';
  var register = function register(qtiCreatorContext, getItem) {
    if (!qtiCreatorContext || qtiCreatorContext._textEntryEvaluationSaveRegistered) {
      return;
    }
    qtiCreatorContext._textEntryEvaluationSaveRegistered = true;
    qtiCreatorContext.trigger('registerBeforeSaveProcess', () => {
      var item = getItem();
      if (!item) {
        return;
      }
      textEntryEvaluationForm.flushOpenForms(item);
      evaluationHelper.ensurePersistedBeforeSave(item);
    });
  };
  return {
    register
  };
});
