define('taoQtiItem/qtiXmlRenderer/helper/responseProcessingTpl',['tpl!taoQtiItem/qtiXmlRenderer/tpl/responses/match_correct', 'tpl!taoQtiItem/qtiXmlRenderer/tpl/responses/map_response', 'tpl!taoQtiItem/qtiXmlRenderer/tpl/responses/map_response_point'], function (correctTpl, mapTpl, mapPointTpl) {
  'use strict';

  var renderRpTpl = (rpTpl, data) => {
    var ret = '';
    switch (rpTpl) {
      case 'http://www.imsglobal.org/question/qti_v2p1/rptemplates/match_correct':
      case 'MATCH_CORRECT':
        ret = correctTpl(data);
        break;
      case 'http://www.imsglobal.org/question/qti_v2p1/rptemplates/map_response':
      case 'MAP_RESPONSE':
        ret = mapTpl(data);
        break;
      case 'http://www.imsglobal.org/question/qti_v2p1/rptemplates/map_response_point':
      case 'MAP_RESPONSE_POINT':
        ret = mapPointTpl(data);
        break;
      case 'no_response_processing':
      case 'NONE':
        ret = '';
        break;
      default:
        throw new Error('unknown rp template : ' + rpTpl);
    }
    return ret;
  };
  return {
    renderInteractionRp(response, outcomeIdentifier) {
      var ret;
      if (response.template) {
        ret = renderRpTpl(response.template, {
          responseIdentifier: response.id(),
          outcomeIdentifier
        });
      }
      return ret;
    }
  };
});
