define('taoQtiItem/qtiCreator/model/helper/event',['jquery', 'lodash'], function ($, _) {
  "use strict";

  var namespace = '.qti-creator';
  var namespaceModel = '.qti-creator';
  var eventList = ['containerBodyChange', 'containerElementAdded', 'elementCreated.qti-widget', 'attributeChange.qti-widget', 'choiceCreated.qti-widget', 'correctResponseChange.qti-widget', 'mapEntryChange.qti-widget', 'mapEntryRemove.qti-widget', 'deleted.qti-widget', 'choiceTextChange.qti-widget', 'responseTemplateChange.qti-widget', 'mappingAttributeChange.qti-widget', 'feedbackRuleConditionChange.qti-widget', 'feedbackRuleCreated.qti-widget', 'feedbackRuleRemoved.qti-widget', 'feedbackRuleElseCreated.qti-widget', 'feedbackRuleElseRemoved.qti-widget'];
  var event = {
    choiceCreated: function choiceCreated(choice, interaction) {
      $(document).trigger('choiceCreated.qti-widget', {
        choice: choice,
        interaction: interaction
      });
    },
    choiceDeleted: function choiceDeleted(choice, interaction) {
      $(document).trigger('choiceDeleted.qti-widget', {
        choice: choice,
        interaction: interaction
      });
    },
    deleted: function deleted(element, parent) {
      if (element.isset()) {
        element.unset();
      }
      $(document).off('.' + element.getSerial());
      $(document).trigger('deleted.qti-widget', {
        element: element,
        parent: parent
      });
    },
    getList: function getList(addedNamespace) {
      var events = _.clone(eventList);
      if (addedNamespace) {
        return _.map(events, function (e) {
          return e + '.' + addedNamespace;
        });
      } else {
        return events;
      }
    },
    initElementToWidgetListeners: function initElementToWidgetListeners() {
      var ns = '.widget-container';
      $(document).off(ns).on(event.getList(ns).join(' '), function (e, data) {
        var element = data.element || data.container || null,
          widget = data && element && element.data('widget');
        if (!widget && data.parent) {
          element = data.parent;
          widget = element.data('widget');
        }
        if (widget) {
          widget.$container.trigger(e.type + namespace + namespaceModel, data);
        }
      });
    },
    getNs: function getNs() {
      return namespace;
    },
    getNsModel: function getNsModel() {
      return namespaceModel;
    }
  };
  return event;
});
