define('taoQtiItem/qtiCreator/widgets/choices/gapText/states/Question',['jquery', 'lodash', 'ckeditor', 'taoQtiItem/qtiCreator/widgets/states/factory', 'taoQtiItem/qtiCreator/widgets/choices/states/Question', 'taoQtiItem/qtiItem/core/Element', 'taoQtiItem/qtiCreator/editor/ckEditor/htmlEditor', 'taoQtiItem/qtiCreator/editor/gridEditor/content'], function ($, _, CKEditor, stateFactory, Question, Element, htmlEditor, contentHelper) {
  'use strict';

  var GapTextStateQuestion = stateFactory.extend(Question, function () {
    this.buildEditor();
  }, function () {
    this.destroyEditor();
  });
  GapTextStateQuestion.prototype.initForm = _.noop();
  GapTextStateQuestion.prototype.buildEditor = function () {
    var _widget = this.widget,
      container = _widget.element.getBody(),
      $editableContainer = _widget.$container;
    $editableContainer.attr('data-html-editable-container', true);
    if (!htmlEditor.hasEditor($editableContainer)) {
      htmlEditor.buildEditor($editableContainer, {
        change: contentHelper.getChangeCallback(container),
        data: {
          container: container,
          widget: _widget
        },
        toolbar: [{
          name: 'basicstyles',
          items: ['Bold', 'Italic', 'Subscript', 'Superscript']
        }, {
          name: 'insert',
          items: ['SpecialChar']
        }, {
          name: 'language',
          items: ['Language']
        }],
        qtiMedia: false,
        qtiInclude: false,
        enterMode: CKEditor.ENTER_BR,
        furiganaPlugin: true
      });
    }
    $editableContainer.on('keypress.qti-widget', function (e) {
      if (e.which === 13) {
        e.preventDefault();
        $(this).blur();
      }
    });
  };
  GapTextStateQuestion.prototype.destroyEditor = function () {
    var _widget = this.widget,
      interaction = _widget.interaction,
      $editableContainer = _widget.$container,
      $editable = $editableContainer.find('[data-html-editable]');
    if (!htmlEditor.hasEditor($editableContainer)) {
      return;
    }
    if ($editable.data('editor')) {
      if (!htmlEditor.getData($editable) || htmlEditor.getData($editable) === '') {
        var placeholder = interaction.getNextPlaceholder();
        htmlEditor.setData($editable, placeholder);
      }
    }
    $editableContainer.off('.qti-widget');
    htmlEditor.destroyEditor(this.widget.$container);
  };
  return GapTextStateQuestion;
});
