define('taoQtiItem/qtiCreator/widgets/helpers/qtiResponseIdentifier',['module', 'i18n'], function (module, __) {
  'use strict';

  var qtiIdPattern = module.config().qtiResponseIdPattern || '/^[a-zA-Z_]{1}[a-zA-Z0-9_.-]*$/u';
  var [, patternContent, flags] = qtiIdPattern.match(/^\/(.+)\/(\w*)$/);
  var defaultInvalidQtiIdMessage = 'Identifiers must start with a letter or an underscore and contain only letters, numbers, dots, underscores ( _ ), or hyphens ( - ).';
  var message = module.config().invalidQtiIdMessage || defaultInvalidQtiIdMessage;
  var invalidQtiIdMessage = __(message);
  var isDisabled = module.config().isDisabled || false;
  return {
    pattern: new RegExp(patternContent, flags),
    invalidQtiIdMessage,
    maxQtiIdLength: 32,
    isDisabled
  };
});
