define('taoQtiItem/qtiCreator/widgets/interactions/sliderInteraction/states/Custom',['taoQtiItem/qtiCreator/widgets/states/factory', 'taoQtiItem/qtiCreator/widgets/states/Custom', 'taoQtiItem/qtiCommonRenderer/renderers/interactions/SliderInteraction', 'taoQtiItem/qtiCommonRenderer/helpers/instructions/instructionManager', 'lodash', 'i18n', 'taoQtiItem/qtiCreator/widgets/interactions/sliderInteraction/Helper', 'taoQtiItem/qtiCreator/widgets/interactions/helpers/answerState'], function (stateFactory, Custom, commonRenderer, instructionMgr, _, __, sliderInteractionHelper, answerState) {
  var SliderInteractionStateCustom = stateFactory.create(Custom, function () {
    _createResponseWidget(this.widget);
  }, function () {
    _destroyResponseWidget(this.widget);
  });
  var _createResponseWidget = function _createResponseWidget(widget) {
    var interaction = widget.element;
    var response = interaction.getResponseDeclaration();
    var correctResponse = _.values(response.getCorrect());
    response.setCorrect(correctResponse);
    commonRenderer.setResponse(interaction, _formatResponse(correctResponse));
    var $sliderElt = widget.$container.find('.qti-slider');
    $sliderElt.removeAttr('disabled');
    instructionMgr.appendInstruction(interaction, __('Please define the correct response using the slider.'));
    widget.$container.on('responseChange.qti-widget', function (e, data) {
      response.setCorrect([data.response.base.integer]);
    });
  };
  var _destroyResponseWidget = function _destroyResponseWidget(widget) {
    answerState.createOutcomeScore(widget);
    var $sliderElt = widget.$container.find('.qti-slider');
    var lowerBound = widget.element.attributes.lowerBound;
    var interaction = widget.element;
    var responseDeclaration = interaction.getResponseDeclaration();
    var currentResponse = _.values(responseDeclaration.getCorrect());
    var responseManager = sliderInteractionHelper.responseManager(interaction, currentResponse);
    widget.isValid('sliderInteraction', responseManager.isValid(), responseManager.getErrorMessage());
    $sliderElt.attr('disabled', 'disabled');
    $sliderElt.val(lowerBound);
    widget.$container.find('span.qti-slider-cur-value').text('' + lowerBound);
    instructionMgr.removeInstructions(widget.element);
    widget.$container.off('responseChange.qti-widget');
  };
  var _formatResponse = function _formatResponse(response) {
    return {
      "base": {
        "integer": response
      }
    };
  };
  return SliderInteractionStateCustom;
});
