define('taoQtiItem/qtiCreator/widgets/interactions/hotspotInteraction/states/Map',['jquery', 'lodash', 'i18n', 'taoQtiItem/qtiCreator/widgets/states/factory', 'taoQtiItem/qtiCreator/widgets/states/Map', 'taoQtiItem/qtiCommonRenderer/renderers/interactions/HotspotInteraction', 'taoQtiItem/qtiCommonRenderer/helpers/instructions/instructionManager', 'taoQtiItem/qtiCommonRenderer/helpers/Graphic', 'taoQtiItem/qtiCommonRenderer/helpers/PciResponse', 'taoQtiItem/qtiCreator/widgets/interactions/helpers/answerState', 'taoQtiItem/qtiCreator/widgets/interactions/helpers/graphicScorePopup', 'tpl!taoQtiItem/qtiCreator/tpl/forms/response/graphicScoreMappingForm', 'taoQtiItem/qtiCreator/widgets/helpers/formElement', 'ui/deleter', 'ui/tooltip'], function ($, _, __, stateFactory, Map, commonRenderer, instructionMgr, graphicHelper, PciResponse, answerStateHelper, grahicScorePopup, mappingFormTpl, formElement, deleter, tooltip) {
  'use strict';
  var initMapState = function initMapState() {
    var widget = this.widget;
    var interaction = widget.element;
    var response = interaction.getResponseDeclaration();
    commonRenderer.resetResponse(interaction);
    commonRenderer.destroy(interaction);
    if (!interaction.paper) {
      return;
    }
    instructionMgr.appendInstruction(interaction, __('Please the score of each hotspot choice.'));
    interaction.responseMappingMode = true;
    interaction.paper = widget.createPaper();
    widget.createChoices();
    initResponseMapping(widget);
    commonRenderer.setResponse(interaction, PciResponse.serialize(_.values(response.getCorrect()), interaction));
  };
  var exitMapState = function exitMapState() {
    var widget = this.widget;
    var interaction = widget.element;
    if (!interaction.paper) {
      return;
    }
    commonRenderer.resetResponse(interaction);
    commonRenderer.destroy(interaction);
    instructionMgr.removeInstructions(interaction);
    interaction.paper = widget.createPaper();
    widget.createChoices();
  };
  function initResponseMapping(widget) {
    var scoreTexts = {};
    var interaction = widget.element;
    var $container = widget.$original;
    var isResponsive = $container.hasClass('responsive');
    var $imageBox = $('.main-image-box', $container);
    var response = interaction.getResponseDeclaration();
    var mapEntries = response.getMapEntries();
    var corrects = _.values(response.getCorrect());
    _.forEach(interaction.getChoices(), function (choice) {
      var shape = interaction.paper.getById(choice.serial);
      var $popup = grahicScorePopup(interaction.paper, shape, $imageBox, isResponsive);
      var scoreDefault = true;
      if (mapEntries[choice.id()]) {
        scoreDefault = false;
      }
      var score = mapEntries[choice.id()] || response.mappingAttributes.defaultValue || '0';
      scoreTexts[choice.serial] = graphicHelper.createShapeText(interaction.paper, shape, {
        id: "score-".concat(choice.serial),
        content: score,
        style: 'score-text-default',
        shapeClick: true
      }).data('default', scoreDefault);
      var $form = $(mappingFormTpl({
        identifier: choice.id(),
        correctDefined: answerStateHelper.isCorrectDefined(widget),
        correct: _.includes(response.getCorrect(), choice.id()),
        score: score,
        scoreMin: response.getMappingAttribute('lowerBound'),
        scoreMax: response.getMappingAttribute('upperBound')
      }));
      formElement.setChangeCallbacks($form, response, {
        score: function score(responseParam, value) {
          var scoreText = scoreTexts[choice.serial];
          if (value === '') {
            responseParam.removeMapEntry(choice.id());
            scoreText.attr({
              text: response.mappingAttributes.defaultValue
            }).data('default', true);
          } else {
            responseParam.setMapEntry(choice.id(), value, true);
            scoreText.attr({
              text: value
            }).data('default', false);
          }
        },
        correct: function correct(responseParam, value) {
          if (value === true) {
            if (!_.includes(corrects, choice.id())) {
              corrects.push(choice.id());
              shape.active = true;
              graphicHelper.updateElementState(shape, 'active');
            }
          } else {
            corrects = _.without(corrects, choice.id());
            shape.active = false;
            graphicHelper.updateElementState(shape, 'basic');
          }
          responseParam.setCorrect(corrects);
        }
      });
      shape.click(function () {
        $('.mapping-editor', $container).hide();
        $popup.show();
      });
      $popup.append($form);
    });
    deleter($container);
    tooltip.lookup($container);
    interaction.paper.getById("bg-image-".concat(interaction.serial)).click(function () {
      $('.mapping-editor', $container).hide();
    });
    $('.mapping-editor', $container).on('click', '.closer', function () {
      $(this).parent('.mapping-editor').hide();
    });
    widget.on('mappingAttributeChange', function (data) {
      if (data.key === 'defaultValue') {
        _.forEach(scoreTexts, function (scoreText) {
          if (scoreText.data('default') === true) {
            scoreText.attr({
              text: data.value
            });
          }
        });
      }
    });
  }
  return stateFactory.create(Map, initMapState, exitMapState);
});
